/**
 * FRAGMENT generation: one inference call per `code` step, each seeing only its contract (`buildFragmentPrompt`), for a flow that
 * carries `code` steps — an imported bundle, or a step regenerated by name. That is all this module does now.
 *
 * ⚠ The single-call drafter, the outline and skeleton pipelines, the draft repair pass and refine that lived here were DELETED at the
 * compiled-builder cutover (phase 8, D-333): a flow is built by the builder (goal → GoalSpec → code) or on the canvas (legal moves
 * only), and no model writes a flow here any more.
 */

import { deriveContractInputs } from "./contract-derive.js";

import type { CatalogueSnapshot } from "@foundry/flow-edit";

import { type InputSuggestion } from "./flow-inputs.js";

import { inference, type InferenceClient } from "./inference.service.js";

import { buildFragmentPrompt, enrichContractWithColumns, parseFragmentResponse, validateFragment, FragmentContractError, type StepContract, type FragmentRefusal } from "./step-contract.service.js";

import { type FlowModel } from "./flow-compiler.service.js";
import { MAX_FRAGMENT_ATTEMPTS } from "./failure-triage.service.js";

/**
 * The placeholder a drafted `code` step carries until its fragment is
 * generated. `flow-compiler.service.ts` rejects it by name (assertion 30), so a
 * draft **cannot** reach Kestra ungenerated — the gap fails at compile time
 * with a sentence about regeneration rather than deploying a `run()` that
 * raises.
 */
export const UNGENERATED = "needs_regeneration";

/**
 * Where a generation has got to.
 *
 * ⚠ `total` is NULL during drafting, and the UI must render that as an
 * INDETERMINATE bar rather than as 0%. Nobody knows how many fragment calls a
 * flow needs until the draft comes back naming its `code` steps, and a bar that
 * shows a made-up denominator is a progress bar that lies — which on a
 * five-minute operation is worse than no bar, because it turns "still working"
 * into "stuck at 12%".
 */
type GenerationProgress = {
  phase: "drafting" | "generating";
  /** Fragment calls completed. Always 0 while drafting. */
  done: number;
  /** Fragment calls required. Null until the draft exists. */
  total: number | null;
  /** The step being generated right now, when there is one. */
  stepId: string | null;
  /**
   * Phase 4 task 5 (D-247) — progressive render. `skeleton`: the outline's steps
   * are known; `wiring`: the wired flow exists; `verified`: the checker's
   * warnings are in. Each later stage REPLACES the graph; a `generating` tick
   * carries the last one forward (the job's writer does that), so the canvas
   * never goes blank while fragments are written. Polled as today — no socket.
   */
  stage?: "skeleton" | "wiring" | "verified";
  graph?: ProgressGraph;
  /** The checker's warnings on the wired flow (errors never reach here — they refuse the draft). */
  diagnostics?: Array<{ code: string; severity: "error" | "warning" | "hole"; span: { stepId?: string; port?: string; field?: string }; message: string; help?: string }>;
};

/** A raw-model-shaped graph: what the client's `canvasFromRawModel` already reads. */
type ProgressGraph = {
  steps: Array<{
    id: string;
    kind: string;
    ref?: string;
    dependsOn: string[];
    elseOf?: string;
    sources?: string[];
    /** Present on a conditioned branch arm; its ABSENCE is what makes an arm the "otherwise". */
    conditionExpr?: string;
  }>;
  /**
   * The flow's entry and exit, so the live canvas draws the SAME Start and End
   * cards the finished flow does. Without them the handoff added two nodes and
   * re-laid-out the whole picture — the jump a person saw when the flow landed.
   * An input's `type` is absent until wiring derives it (D-272).
   */
  inputs?: Array<{ id: string; type?: string }>;
  output?: { stepId: string };
  schedule?: { cron: string; timezone?: string };
};

type ProgressFn = (p: GenerationProgress) => void;

interface FlowDraft {
  model: FlowModel;
  /** One per `code` step, keyed by step id. Empty for a flow with no `code` step. */
  contracts: Record<string, StepContract>;
  /**
   * Input values the drafter PROPOSED, taken out of the model (Phase 4.3).
   *
   * ⚠ Carried, never applied. A suggestion that reached the compiled YAML would
   * be a value nobody supplied deciding what a scheduled run does.
   */
  suggestions: InputSuggestion[];
  notes?: string;
  manifestVersion: number;
}

// ── Stage 2: one fragment, one call ──────────────────────────────────────────

export interface FragmentOutcome {
  stepId: string;
  status: "ok" | "insufficient_contract";
  /** Present when `status === "ok"`. */
  code?: string;
  /** Present when the generator refused. Names the fix. */
  missing?: string[];
  reason?: string;
  /** Inference calls spent on this step. >1 means static findings were fed back. */
  attempts: number;
}

/**
 * Generate ONE fragment from ONE contract.
 *
 * The prompt is `buildFragmentPrompt(contract)` and nothing is added to it —
 * no goal, no manifest, no sibling, no tool catalogue. A retry APPENDS the
 * static findings after the contract, so attempt 2's prompt still contains
 * attempt 1's prompt as a literal prefix.
 *
 * A **refusal ends the loop immediately.** Retrying an `insufficient_contract`
 * is the one thing that must never happen: the answer is correct, the step's
 * inputs really are insufficient, and re-asking is how a correct refusal gets
 * converted into an invented value on attempt 2. It routes to a flow-level
 * redraft (triage level 0) instead.
 */
async function generateFragment(
  contract: StepContract,
  client: InferenceClient = inference,
): Promise<FragmentOutcome> {
  const base = buildFragmentPrompt(contract);
  let findings: string[] = [];
  let lastError = "";

  for (let attempt = 1; attempt <= MAX_FRAGMENT_ATTEMPTS; attempt++) {
    const prompt = findings.length
      ? `${base}\n\nTHE PREVIOUS ATTEMPT WAS REJECTED. Fix exactly these:\n` +
        findings.map((f) => `  - ${f}`).join("\n")
      : base;

    const raw = await client.complete(prompt, { label: `fragment:${contract.stepId}` });

    let response;
    try {
      response = parseFragmentResponse(raw, contract.stepId);
    } catch (e) {
      lastError = (e as FragmentContractError).message;
      findings = [lastError];
      continue;
    }

    if (response.status === "insufficient_contract") {
      const refusal = response as FragmentRefusal;
      return {
        stepId: contract.stepId,
        status: "insufficient_contract",
        missing: refusal.missing,
        reason: refusal.reason,
        attempts: attempt,
      };
    }

    const staticFindings = validateFragment(response.code, contract);
    if (staticFindings.length) {
      findings = staticFindings.map((f) => f.message);
      lastError = findings.join(" · ");
      continue;
    }

    return { stepId: contract.stepId, status: "ok", code: response.code, attempts: attempt };
  }

  throw new FragmentContractError(
    `fragment for "${contract.stepId}" failed ${MAX_FRAGMENT_ATTEMPTS} attempts: ${lastError}`,
    contract.stepId,
  );
}

interface GenerationOutcome {
  /** Every fragment filled in — only when `refusals` is empty. */
  model: FlowModel;
  contracts: Record<string, StepContract>;
  fragments: FragmentOutcome[];
  /** Non-empty → the FLOW is redrafted (triage level 0), not the fragment. */
  refusals: FragmentOutcome[];
  /** Total inference calls spent on fragments. Assertion 18 counts this. */
  inferenceCalls: number;
}

/**
 * Stage 2 over a whole draft: **one call per `code` step, and a step's prompt
 * is a function of its contract alone.**
 *
 * Sequential rather than concurrent, and that is a choice worth stating.
 * Generation is decode-bound at ~37 tok/s, so N fragments in parallel would be
 * roughly N× faster — but the runtime kept `activeRuns` in memory with no boot
 * reconciliation (CLAUDE.md), so a fleet of concurrent runs multiplies the
 * orphan surface of a known defect. Fragments are small; sequential is the
 * conservative default until that defect is fixed.
 */
export async function generateFragments(
  // ⚠ `Pick`, not `FlowDraft`. This function generates a fragment per `code`
  // step and touches nothing else — in particular it has no business with
  // `suggestions`, which are a question for a person and not an input to
  // inference. Widening to the whole draft made three callers (an import, a
  // harness and a test) construct fields they have no opinion about.
  draft: Pick<FlowDraft, "model" | "contracts">,
  client: InferenceClient = inference,
  onProgress?: ProgressFn,
  /**
   * The workspace's `refInterfaces`, when the caller has them. The SAME column
   * source the chat turn's owed loop reads (`specJson.columns[].alias` via
   * `manifest-builder`), copied into each owed contract's input descriptions by
   * `enrichContractWithColumns` — prompt-time only, so the returned
   * `contracts` are still the declared ones below. Absent (the harness, older
   * tests) behaves as `{}`: no enrichment, byte-identical prompts.
   */
  interfaces: Record<string, { columns?: string[] }> = {},
  /**
   * The checker's catalogue snapshot (phase 5, D-254): with it, each typed
   * contract input is DERIVED from its source's output type
   * (`deriveContractInputs`). Absent behaves as before — prompt-time only
   * either way, the returned contracts are the declared ones.
   */
  catalogue?: CatalogueSnapshot,
): Promise<GenerationOutcome> {
  const fragments: FragmentOutcome[] = [];
  let calls = 0;

  // Counted BEFORE the loop, because the number of fragment calls is the only
  // part of a generation whose size is knowable in advance — and it is what
  // makes a determinate progress bar honest rather than decorative. Most steps
  // are never generated at all: the five-step reference flow has three.
  const total = draft.model.steps.filter((s) => s.kind === "code").length;
  let done = 0;
  onProgress?.({ phase: "generating", done, total, stepId: null });

  for (const step of draft.model.steps) {
    if (step.kind !== "code") continue;
    const contract = draft.contracts[step.id];
    if (!contract) {
      throw new FragmentContractError(`no contract for code step "${step.id}"`, step.id);
    }
    onProgress?.({ phase: "generating", done, total, stepId: step.id });
    /**
     * ⚠ F1 on the draft path — the same enrichment the chat turn's owed loop
     * applies, for the same measured reason (`compute_figures` refusing over
     * `missing: ["row schema", "amount units/scale"]` while the projection sat
     * in the row). Prompt-time only: the `contracts` returned below are still
     * the declared ones (`draft.contracts`, same reference) — only the copy
     * `generateFragment` sees carries the columns.
     */
    const outcome = await generateFragment(
      enrichContractWithColumns(deriveContractInputs(contract, draft.model, catalogue), draft.model, interfaces),
      client,
    );
    calls += outcome.attempts;
    fragments.push(outcome);
    done++;
    onProgress?.({ phase: "generating", done, total, stepId: null });
  }

  const refusals = fragments.filter((f) => f.status === "insufficient_contract");
  return {
    model: refusals.length ? draft.model : applyFragments(draft.model, fragments),
    contracts: draft.contracts,
    fragments,
    refusals,
    inferenceCalls: calls,
  };
}

/** Write generated bodies back into a model. Pure — the input model is untouched. */
function applyFragments(model: FlowModel, fragments: FragmentOutcome[]): FlowModel {
  const byId = new Map(fragments.filter((f) => f.code).map((f) => [f.stepId, f.code!]));
  return {
    ...model,
    steps: model.steps.map((s) =>
      s.kind === "code" && byId.has(s.id) ? { ...s, code: byId.get(s.id)! } : s,
    ),
  };
}

/**
 * Regenerate exactly ONE step.
 *
 * Assertion 19 — *"regenerate B and A and C stay byte-identical"* — is a
 * property of this function, and it holds because a fragment is a function of
 * its contract and nothing else. There is no shared session carrying A's code
 * into B's context (see `inference.service.ts`), no shared prompt state, and no
 * step of the returned model is rewritten except the named one.
 *
 * It is what makes triage level 1 cheap: a `contract_violation` in one step
 * costs one fragment, not a redraft of the flow.
 */
export async function regenerateStep(
  model: FlowModel,
  contracts: Record<string, StepContract>,
  stepId: string,
  client: InferenceClient = inference,
): Promise<{ model: FlowModel; outcome: FragmentOutcome }> {
  const step = model.steps.find((s) => s.id === stepId);
  if (!step || step.kind !== "code") {
    throw new FragmentContractError(`"${stepId}" is not a code step in this flow`, stepId);
  }
  const contract = contracts[stepId];
  if (!contract) throw new FragmentContractError(`no contract for code step "${stepId}"`, stepId);

  const outcome = await generateFragment(contract, client);
  return {
    model: outcome.code ? applyFragments(model, [outcome]) : model,
    outcome,
  };
}
